"""Verify and seal the selected R109 E48 checkpoint."""
from __future__ import annotations
import csv,hashlib,json,shutil
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];RUN=ROOT/'runs/r109_formal_scratch_continuous_b8_20260826';SOURCE=RUN/'weights/epoch_048.pth';SELECTED=ROOT/'weights/selected/R109.pth'
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main():
 state=json.loads((RUN/'run_state.json').read_text(encoding='utf-8'));history=json.loads((RUN/'training_history.json').read_text(encoding='utf-8'));checkpoints=sorted((RUN/'weights').glob('epoch_*.pth'));previews=sorted((RUN/'previews').glob('epoch_*.png'));motion=json.loads((ROOT/'results/posttraining_motion/E048/summary.json').read_text(encoding='utf-8'))
 if state.get('status')!='complete' or state.get('epochs_completed')!=48 or len(history)!=48 or len(checkpoints)!=12 or len(previews)!=12 or not motion.get('all_sequences_pass'):raise RuntimeError('Formal completion evidence mismatch')
 external={}
 for suite in ('R73','R74'):
  table=pd.read_csv(ROOT/f'results/posttraining_acm/E048/{suite}/results/tables/primary_contour_metrics.csv');table=table[table.alignment=='translation_only'];raw=table[table.method=='Raw'];model=table[table.method!='Raw'];external[suite]={'primary_alignment':'translation_only','raw_boundary_px':float(raw.mean_boundary_distance_px.median()),'model_boundary_px':float(model.mean_boundary_distance_px.median()),'raw_iou':float(raw.iou.median()),'model_iou':float(model.iou.median()),'families_improved':int(sum(model.groupby('family').mean_boundary_distance_px.median()<raw.groupby('family').mean_boundary_distance_px.median())),'raw_perimeter_error_pct':float(raw.perimeter_error_pct.median()),'model_perimeter_error_pct':float(model.perimeter_error_pct.median())}
 sem=pd.read_csv(ROOT/'results/posttraining_acm/E048/SEM/results/tables/primary_contour_metrics.csv');pillar=sem.groupby(['method','pillar_id'])[['iou','mean_boundary_distance_pitch_pct','area_error_pct','perimeter_error_pct']].median().groupby('method').median();raw= pillar.loc['Raw'];model=pillar.loc['R109_E048'];external['SEM_per_pillar']={'raw_boundary_pitch_pct':float(raw.mean_boundary_distance_pitch_pct),'model_boundary_pitch_pct':float(model.mean_boundary_distance_pitch_pct),'raw_iou':float(raw.iou),'model_iou':float(model.iou),'raw_area_error_pct':float(raw.area_error_pct),'model_area_error_pct':float(model.area_error_pct),'raw_perimeter_error_pct':float(raw.perimeter_error_pct),'model_perimeter_error_pct':float(model.perimeter_error_pct)}
 SELECTED.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(SOURCE,SELECTED)
 if sha(SOURCE)!=sha(SELECTED):raise RuntimeError('Selected checkpoint copy hash mismatch')
 appearance=pd.read_csv(ROOT/'results/posttraining_motion/E048/appearance_sequence_summary.csv');motion_table=pd.read_csv(ROOT/'results/posttraining_motion/E048/motion_sequence_summary.csv');selection={'status':'selected','experiment':'R109_StagedMidpointWidthScratch','selected_epoch':48,'selected_checkpoint':str(SELECTED),'selected_checkpoint_sha256':sha(SELECTED),'source_checkpoint':str(SOURCE),'formal_run':'r109_formal_scratch_continuous_b8_20260826','formal_training':{'epochs':48,'global_steps':30000,'elapsed_seconds':state['elapsed_seconds'],'scratch':True,'weights_inherited':False},'external_acm':external,'motion':{'frames':301,'measurements':6672,'all_six_sequences_pass':True,'maximum_scale_error_fraction':float(motion_table.median_scale_error_fraction.max()),'maximum_median_vector_difference_um':float(motion_table.median_vector_difference_from_raw_um.max()),'direction_agreement_min':float(motion_table.direction_agreement.min())},'appearance':{'five_x_detail_ratio':float(appearance[appearance.sequence.str.startswith('5x')].fine_detail_energy_ratio.median()),'twenty_x_detail_ratio':float(appearance[appearance.sequence.str.startswith('20x')].fine_detail_energy_ratio.median()),'fifty_x_detail_ratio':float(appearance[appearance.sequence.str.startswith('50x')].fine_detail_energy_ratio.median()),'maximum_off_source_strong_edge_fraction':float(appearance.off_source_strong_edge_fraction.max()),'dark_ring_visible':False},'role':'selected R109 research candidate; not yet ONNX or enterprise delivery','comparison_boundary':'R109 is the strongest newly trained cross-scene scratch candidate, but R79E23 remains stronger on SEM-only truth and project formal-baseline replacement still requires a sealed final comparison.'}
 (ROOT/'results/FINAL_SELECTION.json').write_text(json.dumps(selection,indent=2),encoding='utf-8')
 report=f'''# R109 E48 最終選擇\n\nR109 的正式從零訓練已完整完成，E48 被選為唯一正式權重。\n\n- R73 邊界：{external['R73']['raw_boundary_px']:.4f} → {external['R73']['model_boundary_px']:.4f}\n- R74 邊界：{external['R74']['raw_boundary_px']:.4f} → {external['R74']['model_boundary_px']:.4f}\n- SEM 每柱邊界：{external['SEM_per_pillar']['raw_boundary_pitch_pct']:.4f} → {external['SEM_per_pillar']['model_boundary_pitch_pct']:.4f}\n- SEM 每柱周長：{external['SEM_per_pillar']['raw_perimeter_error_pct']:.4f} → {external['SEM_per_pillar']['model_perimeter_error_pct']:.4f}\n- 真實位移：301 張、6672 筆、六組全數通過。\n- 5× 幾乎保持原圖，20× 中度增強，50× 明顯增強；沒有肉眼黑環。\n\n選定權重：`weights/selected/R109.pth`\n\nR109 是目前最強的新一代跨場景從零訓練候選，但尚未取代專案正式基準，也尚未打包 ONNX。R79 E23 在 SEM 專項真值仍明顯更強，最終替代必須經過封閉比較。\n''';(ROOT/'reports/R109_FINAL_SELECTION_ZH.md').write_text(report,encoding='utf-8')
 selected_files=[ROOT/'config/experiment.json',ROOT/'model/r109_model.py',ROOT/'training/r109_dataset.py',ROOT/'training/losses.py',ROOT/'training/train.py',ROOT/'inference/run_folder.py',ROOT/'results/FINAL_SELECTION.json',ROOT/'reports/R109_FINAL_SELECTION_ZH.md',SELECTED]
 with (ROOT/'FINAL_SELECTED_MANIFEST_SHA256.csv').open('w',newline='',encoding='utf-8-sig') as handle:
  writer=csv.DictWriter(handle,fieldnames=['relative_path','bytes','sha256']);writer.writeheader()
  for path in selected_files:writer.writerow({'relative_path':path.relative_to(ROOT).as_posix(),'bytes':path.stat().st_size,'sha256':sha(path)})
 print(json.dumps({'status':'selected','epoch':48,'checkpoint':str(SELECTED),'sha256':sha(SELECTED)}),flush=True);return 0
if __name__=='__main__':raise SystemExit(main())
